'use strict';
(globalThis.G2G || (globalThis.G2G = {})).gameSource = "// BRICKFALL: a breakout game in Tin, for the G16.\n//\n// The screen is 64 x 48 words at SCREEN, one word per pixel, holding a\n// colour from 0 to 15. The game keeps no map of the bricks: the screen is the\n// map. The ball looks at the colour of the pixel it is about to enter.\n\nconst SCREEN = 16384;          // 0x4000\nconst KEYS = 24576;            // 0x6000: bit 0 left, bit 1 right, bit 2 launch\nconst TICK = 24577;            // counts video frames (60 a second)\n\nconst W = 64;\nconst H = 48;\nconst WALL = 1;                // colours 2..13 are bricks\nconst PADDLE = 14;\nconst BALL = 15;\nconst HUD = 14;\n\nconst TOP = 6;                 // the top wall's row\nconst BRICK_Y = 9;             // first brick row\nconst ROWS = 6;\nconst COLS = 15;\nconst BRICK_X = 2;\nconst PADDLE_Y = 44;\nconst PADDLE_W = 8;\n\nvar row[48];                   // address of each screen row\nvar font[] = {0x7B6F, 0x749A, 0x73E7, 0x79E7, 0x49ED, 0x79CF, 0x7BCF, 0x24A7, 0x7BEF, 0x79EF};\nvar english[] = {-14, -10, -6, -3, 3, 6, 10, 14};   // ball vx by where it hits the paddle\n\nvar px = 28;                   // paddle, left end\nvar bx = 0; var by = 0;        // ball, in pixels\nvar bx16 = 0; var by16 = 0;    // ball, in sixteenths of a pixel\nvar vx = 0; var vy = 0;        // sixteenths of a pixel per frame\nvar speed = 10;\nvar held = 1;                  // ball resting on the paddle\nvar hold_time = 0;\nvar score = 0; var lives = 3; var level = 1;\nvar bricks = 0;\nvar idle = 0;                  // frames since a key was pressed\nvar frame = 0;\nvar rnd = 0x5EED;\nvar over = 0;\n\nfunc random() {\n  // A 16-bit Galois LFSR, shifted left: x^16 + x^5 + x^3 + x^2 + 1.\n  if (rnd < 0) rnd = (rnd + rnd) ^ 0x2D; else rnd = rnd + rnd;\n  return rnd;\n}\n\nfunc pixel(x, y) { return mem[row[y] + x]; }\n\nfunc fill(x, y, w, h, c) {\n  var y1 = y + h;\n  while (y < y1) {\n    var a = row[y] + x;\n    var a1 = a + w;\n    while (a < a1) { mem[a] = c; a++; }\n    y++;\n  }\n}\n\nfunc draw_digit(d, x, y) {\n  var g = font[d];\n  var m = 1;\n  var a = row[y] + x;\n  for (var r = 0; r < 5; r++) {\n    for (var c = 0; c < 3; c++) {\n      if (g & m) mem[a + c] = HUD; else mem[a + c] = 0;\n      m += m;\n    }\n    a += W;\n  }\n}\n\nfunc draw_number(n, x, y) {\n  var unit = 1000;\n  while (unit) {\n    var d = 0;\n    while (n >= unit) { n -= unit; d++; }\n    draw_digit(d, x, y);\n    x += 4;\n    if (unit == 1000) unit = 100; else if (unit == 100) unit = 10; else if (unit == 10) unit = 1; else unit = 0;\n  }\n}\n\nfunc draw_hud() {\n  draw_number(score, 1, 0);\n  for (var i = 0; i < 3; i++) {\n    var c = 0;\n    if (i < lives) c = PADDLE;\n    fill(44 + i * 4, 2, 3, 1, c);\n  }\n  draw_digit(level % 10, 60, 0);\n}\n\nfunc draw_bricks() {\n  bricks = 0;\n  for (var r = 0; r < ROWS; r++) {\n    for (var c = 0; c < COLS; c++) {\n      fill(BRICK_X + c * 4, BRICK_Y + r * 2, 4, 2, 2 + r * 2 + (c & 1));\n      bricks++;\n    }\n  }\n}\n\nfunc draw_walls() {\n  fill(0, TOP, W, 1, WALL);\n  fill(0, TOP + 1, 1, H - TOP - 1, WALL);\n  fill(W - 1, TOP + 1, 1, H - TOP - 1, WALL);\n}\n\nfunc serve() {\n  // Put the ball on the paddle and wait for a launch.\n  held = 1;\n  hold_time = 0;\n  bx = px + 3 + (random() & 1);\n  by = PADDLE_Y - 1;\n  bx16 = (bx << 4) + 8;\n  by16 = (by << 4) + 8;\n  mem[row[by] + bx] = BALL;\n}\n\nfunc launch() {\n  held = 0;\n  vy = -speed;\n  vx = english[2 + (random() & 3)];\n}\n\nfunc new_game() {\n  fill(1, TOP + 1, W - 2, H - TOP - 1, 0);\n  score = 0; lives = 3; level = 1; speed = 10; over = 0;\n  draw_bricks();\n  draw_hud();\n  fill(px, PADDLE_Y, PADDLE_W, 1, PADDLE);\n  serve();\n}\n\nfunc break_brick(x, y) {\n  var c = (x - BRICK_X) >> 2;\n  var r = (y - BRICK_Y) >> 1;\n  fill(BRICK_X + (c << 2), BRICK_Y + (r << 1), 4, 2, 0);\n  score += ROWS - r;\n  bricks--;\n  draw_number(score, 1, 0);\n}\n\n// The ball is about to enter a pixel of colour c at (x, y).\nfunc hit(x, y, c, vertical) {\n  if (c >= 2 && c <= 13) break_brick(x, y);\n  if (vertical) {\n    if (c == PADDLE && vy > 0) {\n      vx = english[x - px];\n      vy = -speed;\n    } else vy = -vy;\n  } else vx = -vx;\n}\n\nfunc lose_ball() {\n  mem[row[by] + bx] = 0;\n  lives--;\n  draw_hud();\n  if (lives == 0) { over = 1; hold_time = 0; return; }\n  serve();\n}\n\nfunc move_ball() {\n  if (held) {\n    // Ride on the paddle.\n    var hx = px + 3;\n    if (hx != bx) {\n      mem[row[by] + bx] = 0;\n      bx = hx;\n      bx16 = (bx << 4) + 8;\n      mem[row[by] + bx] = BALL;\n    }\n    hold_time++;\n    return;\n  }\n  var nx16 = bx16 + vx;\n  var ny16 = by16 + vy;\n  var nx = nx16 >> 4;\n  var ny = ny16 >> 4;\n  if (ny >= H) { lose_ball(); return; }\n  if (nx == bx && ny == by) { bx16 = nx16; by16 = ny16; return; }\n  var bounced = 0;\n  if (nx != bx) {\n    var c = pixel(nx, by);\n    if (c) { hit(nx, by, c, 0); bounced = 1; }\n  }\n  if (ny != by) {\n    var c2 = pixel(bx, ny);\n    if (c2) { hit(bx, ny, c2, 1); bounced = 1; }\n  }\n  if (!bounced && nx != bx && ny != by) {\n    var c3 = pixel(nx, ny);\n    if (c3) { hit(nx, ny, c3, 1); vx = -vx; bounced = 1; }\n  }\n  if (bounced) return;\n  if (pixel(bx, by) == BALL) mem[row[by] + bx] = 0;\n  mem[row[ny] + nx] = BALL;\n  bx = nx; by = ny; bx16 = nx16; by16 = ny16;\n}\n\nfunc move_paddle() {\n  var k = mem[KEYS];\n  var dir = 0;\n  if (k) idle = 0; else idle++;\n  if (k & 1) dir = -1;\n  if (k & 2) dir = 1;\n  if (idle > 180) {\n    // Nobody is playing: follow the ball, aiming a little off-centre.\n    var aim = bx - 3 - ((frame >> 7) & 3) + 1;\n    if (held) aim = 28 + ((frame >> 5) & 15) - 8;\n    if (aim < px) dir = -1;\n    if (aim > px) dir = 1;\n    if (held && hold_time > 60) launch();\n  }\n  if (k & 4) { if (held) launch(); }\n  if (dir < 0 && px > 1) {\n    mem[row[PADDLE_Y] + px + PADDLE_W - 1] = 0;\n    px--;\n    mem[row[PADDLE_Y] + px] = PADDLE;\n  }\n  if (dir > 0 && px + PADDLE_W < W - 1) {\n    mem[row[PADDLE_Y] + px] = 0;\n    px++;\n    mem[row[PADDLE_Y] + px + PADDLE_W - 1] = PADDLE;\n  }\n}\n\nfunc wait_frame() {\n  var t = mem[TICK];\n  while (mem[TICK] == t) { }\n}\n\nfunc main() {\n  for (var y = 0; y < H; y++) row[y] = SCREEN + (y << 6);\n  draw_walls();\n  new_game();\n  while (1) {\n    wait_frame();\n    frame++;\n    random();\n    if (over) {\n      hold_time++;\n      if (hold_time > 150 || (hold_time > 30 && mem[KEYS])) new_game();\n      continue;\n    }\n    move_paddle();\n    move_ball();\n    if (bricks == 0) {\n      level++;\n      if (speed < 14) speed += 1;\n      mem[row[by] + bx] = 0;\n      draw_bricks();\n      draw_hud();\n      serve();\n    }\n  }\n}\n";
